def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # dp[i][j][k][l] will be the maximum value collected by two paths
    # where one path ends at (i, j) and the other at (k, l)
    dp = [[[[0] * N for _ in range(N)] for _ in range(N)] for _ in range(N)]

    # Initialize the starting point
    dp[0][0][0][0] = grid[0][0]

    # Fill the dp table
    for i in range(N):
        for j in range(N):
            for k in range(N):
                for l in range(N):
                    if (i, j) == (0, 0) and (k, l) == (0, 0):
                        continue
                    if i > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i-1][j][k][l])
                    if j > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j-1][k][l])
                    if k > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j][k-1][l])
                    if l > 0:
                        dp[i][j][k][l] = max(dp[i][j][k][l], dp[i][j][k][l-1])

                    value1 = grid[i][j] if (i, j) == (k, l) else grid[i][j] + grid[k][l]
                    dp[i][j][k][l] += value1

    return dp[N-1][N-1][N-1][N-1]

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
    avg_score, eval_score = grades
    scholarship = 0

    if avg_score > 80 and papers > 0:
        scholarship += 8000
    if avg_score > 85 and eval_score > 80:
        scholarship += 4000
    if avg_score > 90:
        scholarship += 2000
    if avg_score > 85 and west == 'Y':
        scholarship += 1000
    if eval_score > 80 and leader == 'Y':
        scholarship += 850

    return scholarship

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    # Build the mapping from encoded to original letters
    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    # Check if all letters in message are representable
    for char in message:
        if char not in mapping:
            return "Failed"

    # Decode the message
    decoded_message = ''.join(mapping[char] for char in message)
    return decoded_message

def generate_numbers(n, rules) -> int:
    from collections import deque

    # Create a dictionary from rules for O(1) look-up
    transformation_dict = {}
    for x, y in rules:
        if x not in transformation_dict:
            transformation_dict[x] = set()
        transformation_dict[x].add(y)

    # BFS to explore all unique numbers
    unique_numbers = set()
    queue = deque([n])
    unique_numbers.add(n)

    while queue:
        current_number = queue.popleft()
        current_str = str(current_number)

        for i in range(len(current_str)):
            digit = int(current_str[i])
            if digit in transformation_dict:
                for new_digit in transformation_dict[digit]:
                    new_number_str = current_str[:i] + str(new_digit) + current_str[i+1:]
                    new_number = int(new_number_str)
                    if new_number not in unique_numbers:
                        unique_numbers.add(new_number)
                        queue.append(new_number)

    return len(unique_numbers)

